mapper.select:
SELECT GROUP_CONCAT(name SEPARATOR '/') as employee_names from area WHERE id in
#{item}
ORDER BY `level` asc

select a.id, a.sequence,a.parent_id,a.level, a.sort, a.name, a.status_id, a.built_up_area, a.feature_ids, a.tag_ids
from `area` a


        and a.name like concat('%',#{queryParam.keyword},'%')


        and a.status_id = #{queryParam.statusId}



            and a.built_up_area < #{queryParam.areaNumber}


            and a.built_up_area <= #{queryParam.areaNumber}


            and a.built_up_area = #{queryParam.areaNumber}


            and a.built_up_area > #{queryParam.areaNumber}


            and a.built_up_area >= #{queryParam.areaNumber}



        and a.feature_ids like concat('%',#{queryParam.featureId},'%')


order by a.sequence

select a.id, a.sequence,a.parent_id,a.level, a.sort, a.name, a.status_id, a.built_up_area, a.feature_ids, a.tag_ids
,`as`.name as statusName, ae.introduce
from `area` a
left join area_status as `as` on (a.status_id = `as`.id)
left join area_extend as ae on (a.id = ae.id)


        and a.name like concat('%',#{queryParam.keyword},'%')


        and a.status_id = #{queryParam.statusId}



            and a.built_up_area < #{queryParam.areaNumber}


            and a.built_up_area <= #{queryParam.areaNumber}


            and a.built_up_area = #{queryParam.areaNumber}


            and a.built_up_area > #{queryParam.areaNumber}


            and a.built_up_area >= #{queryParam.areaNumber}



        and a.feature_ids like concat('%',#{queryParam.featureId},'%')


        and a.sequence in

            #{item}



order by a.sequence
